tcb_info.app_compose:
{
    "manifest_version": 2,
    "name": "dstack-gateway",
    "runner": "docker-compose",
    "docker_compose_file": "# SPDX-FileCopyrightText: © 2025 Phala Network <dstack@phala.network>
#
# SPDX-License-Identifier: Apache-2.0

services:
  gateway:
    image: ghcr.io/dstack-tee/dstack-gateway:0.6.1@sha256:d99e156cb002591fe65716b0eed232ca4eea199d25f1fce55dd5274ba608ff32
    volumes:
      - /var/run/dstack.sock:/var/run/dstack.sock
      - /dstack:/dstack
      - data:/data
    network_mode: host
    privileged: true
    environment:
      - WG_ENDPOINT=${WG_ENDPOINT}
      - MY_URL=${MY_URL}
      - BOOTNODE_URL=${BOOTNODE_URL}
      - WG_IP=${WG_IP}
      - WG_RESERVED_NET=${WG_RESERVED_NET}
      - WG_CLIENT_RANGE=${WG_CLIENT_RANGE}
      - NODE_ID=${NODE_ID}
      - RUST_LOG=info,certbot=debug
      - PCCS_URL=${PCCS_URL}
      - RPC_DOMAIN=${RPC_DOMAIN}
      - PROXY_LISTEN_PORT=${PROXY_LISTEN_PORT:-443}
      - PROXY_WORKERS=${PROXY_WORKERS:-32}
      - MAX_CONNECTIONS_PER_APP=${MAX_CONNECTIONS_PER_APP:-0}
      - INBOUND_PP_ENABLED=${INBOUND_PP_ENABLED:-true}
      - TIMEOUT_PP_HEADER=${TIMEOUT_PP_HEADER:-5s}
      - PORT_POLICY_FETCH_TIMEOUT=${PORT_POLICY_FETCH_TIMEOUT:-10s}
      - PORT_POLICY_FETCH_MAX_RETRIES=${PORT_POLICY_FETCH_MAX_RETRIES:-5}
      - PORT_POLICY_FETCH_BACKOFF_INITIAL=${PORT_POLICY_FETCH_BACKOFF_INITIAL:-1s}
      - PORT_POLICY_FETCH_BACKOFF_MAX=${PORT_POLICY_FETCH_BACKOFF_MAX:-30s}
      - SYNC_INTERVAL=${SYNC_INTERVAL:-1m}
      - SYNC_TIMEOUT=${SYNC_TIMEOUT:-2m}
      - SYNC_PERSIST_INTERVAL=${SYNC_PERSIST_INTERVAL:-5m}
      - SYNC_CONNECTIONS_ENABLED=${SYNC_CONNECTIONS_ENABLED:-true}
      - SYNC_CONNECTIONS_INTERVAL=${SYNC_CONNECTIONS_INTERVAL:-30s}
      - TIMEOUT_CONNECT=${TIMEOUT_CONNECT:-5s}
      - TIMEOUT_HANDSHAKE=${TIMEOUT_HANDSHAKE:-5s}
      - TIMEOUT_CACHE_TOP_N=${TIMEOUT_CACHE_TOP_N:-30s}
      - TIMEOUT_DNS_RESOLVE=${TIMEOUT_DNS_RESOLVE:-5s}
      - TIMEOUT_DATA_ENABLED=${TIMEOUT_DATA_ENABLED:-true}
      - TIMEOUT_IDLE=${TIMEOUT_IDLE:-10m}
      - TIMEOUT_WRITE=${TIMEOUT_WRITE:-5s}
      - TIMEOUT_SHUTDOWN=${TIMEOUT_SHUTDOWN:-5s}
      - TIMEOUT_TOTAL=${TIMEOUT_TOTAL:-5h}
      - ADMIN_LISTEN_ADDR=${ADMIN_LISTEN_ADDR:-0.0.0.0}
      - ADMIN_LISTEN_PORT=${ADMIN_LISTEN_PORT:-8001}
      - ADMIN_API_TOKEN=${ADMIN_API_TOKEN}
    healthcheck:
      test: ["CMD", "curl", "-sf", "-H", "Authorization: Bearer ${ADMIN_API_TOKEN}", "http://127.0.0.1:${ADMIN_LISTEN_PORT:-8001}/prpc/Status"]
      interval: 30s
      timeout: 5s
      retries: 3
      start_period: 30s
    restart: always

volumes:
  data:
",
    "kms_enabled": true,
    "gateway_enabled": false,
    "local_key_provider_enabled": false,
    "key_provider_id": "",
    "public_logs": true,
    "public_sysinfo": true,
    "allowed_envs": [
        "RPC_DOMAIN",
        "WG_ENDPOINT",
        "MY_URL",
        "BOOTNODE_URL",
        "NODE_ID",
        "WG_IP",
        "WG_RESERVED_NET",
        "WG_CLIENT_RANGE",
        "ADMIN_API_TOKEN",
        "APP_LAUNCH_TOKEN"
    ],
    "no_instance_id": true,
    "secure_time": false,
    "pre_launch_script": "ACTUAL_TOKEN_HASH=$(echo -n "$APP_LAUNCH_TOKEN" | sha256sum | cut -d' ' -f1)
if [ "649f563b509f3a68b8038d5d6f25e568910b4921bf954b650c9629ab4480c01a" != "$ACTUAL_TOKEN_HASH" ]; then
    echo "Error: Incorrect APP_LAUNCH_TOKEN, please make sure set the correct APP_LAUNCH_TOKEN in env"
    reboot
    exit 1
else
    echo "APP_LAUNCH_TOKEN checked OK"
fi
",
    "launch_token_hash": "649f563b509f3a68b8038d5d6f25e568910b4921bf954b650c9629ab4480c01a"
}
